import{_ as O,l as o,o as i,b as p,q as d,d as t,f as S,m as l}from"./chunks/framework.Tf23FRXt.js";const k=JSON.parse('{"title":"雪山奥窟冥魂石洞","description":"","frontmatter":{},"headers":[{"level":2,"title":"进场 ~ BOSS 1","slug":"进场-boss-1","link":"#进场-boss-1","children":[]},{"level":2,"title":"BOSS 1 ~ BOSS 2","slug":"boss-1-boss-2","link":"#boss-1-boss-2","children":[]},{"level":2,"title":"BOSS 2 ~ BOSS 3","slug":"boss-2-boss-3","link":"#boss-2-boss-3","children":[]}],"relativePath":"duty/896.htm.md","filePath":"duty/896.md","lastUpdated":1791098838000}'),r={name:"duty/896.htm.md"};function a(m,s,B,b,u,A){const e=o("Status"),n=o("Role");return i(),p("div",null,[s[6]||(s[6]=d('<h1 id="雪山奥窟冥魂石洞" tabindex="-1">雪山奥窟冥魂石洞</h1><h2 id="进场-boss-1" tabindex="-1">进场～BOSS 1</h2><p>狮鹫吃眩晕，AOE 可以使用眩晕打断。</p><h1 id="boss-1-白雪兽" tabindex="-1">BOSS 1 白雪兽</h1><p>开场读条<mark>野性呼唤</mark>后，画面提示<ins>有什么东西正在靠近……</ins>，此时观察场地两侧，会有某个位置的树林扬起白色的雪雾，躲开有雪雾的位置，一会会有一大堆野兽从这个位置冲出来造成直线 AOE 伤害（野兽不可选中不可攻击，直线宽度大约 1/4 场地），第一波野兽冲完之后，会紧跟第二波野兽（一定出现在不同位置）。</p><p>读条<mark>〇侧猛击</mark>，观察 BOSS 面向，向其反方向躲避。</p><p>BOSS 召唤 3 个冰坨后，会先瞄准并杂碎其中一个冰坨（需要远离），之后有一个分散机制，然后 BOSS 跳回场中释放全屏 AOE，此时需要在剩余的冰坨后方躲避。</p><p>最后会有猛兽乱冲 +〇侧猛击的组合机制，冷静处理即可。</p><h2 id="boss-1-boss-2" tabindex="-1">BOSS 1 ~ BOSS 2</h2><p>没有特别要注意的</p><h1 id="boss-2-大型伽拉忒亚人偶" tabindex="-1">BOSS 2 大型伽拉忒亚人偶</h1><p>读条<mark>环割圆切</mark>，是环形 AOE 接圆形 AOE。衔接时间非常短，需要在 AOE 提示范围边缘等待，环形 AOE 结束后立刻向外移动。</p><p>读条<mark>灵魂钐割</mark>，BOSS 面向范围巨大圆形 AOE，在 BOSS 正后方躲避即可。</p><p>BOSS 全屏 AOE 并召唤传送门，脚下出现 X 形特殊 AOE 范围预警，读条<mark>人偶追逐</mark>。观察传送门上方显示的点数，读条结束后，BOSS 会按点数依次跳到传送门上方，释放以自己目标圈直径为宽度的 X 形 AOE。</p><ul><li>第一次站在场地中央处理即可</li><li>第二次观察中央的传送门的数字：比如是 3，那么在 BOSS 攻击第 2 次的时候离开场地中央，第 3 次攻击完回到场地中央即可。</li></ul>',15)),t("p",null,[s[0]||(s[0]=S("场地 4 个塔，一人踩一个，踩塔结束后会立刻接背对机制",-1)),l(e,{id:3511,name:"人偶石眼"}),s[1]||(s[1]=S("，踩完塔后面向场外等 debuff 倒计时结束即可。",-1))]),s[7]||(s[7]=t("p",null,[S("读条"),t("mark",null,"圆切环割"),S("，和开场相反，先圆形 AOE 再环形 AOE，处理方法相同。")],-1)),s[8]||(s[8]=t("h2",{id:"boss-2-boss-3",tabindex:"-1"},"BOSS 2 ~ BOSS 3",-1)),s[9]||(s[9]=t("p",null,"没什么特别的。",-1)),s[10]||(s[10]=t("h1",{id:"boss-3-凯纳槽",tabindex:"-1"},"BOSS 3 凯纳槽",-1)),s[11]||(s[11]=t("p",null,[S("读条"),t("mark",null,"古洪将至"),S("后，BOSS 分 3 次召唤水球，水球会依次炸开巨大范围的 AOE。观察 3 次水球的位置，在第二波水球下方等待第一波水球炸开后，移动到第一波水球下方躲避第二波水球，然后立刻向场地中央靠近（不要踩进紫圈），击退处理第三波水球。")],-1)),s[12]||(s[12]=t("p",null,"BOSS 跳到场边并出现连续冲锋预兆，冷静观察并选择合适位置回避，如果实在避不开可以吃一下，别吃多了。",-1)),t("p",null,[s[2]||(s[2]=S("中间打柱子阶段会伴有分散分摊，注意打的时候别忘了处理机制。打完柱子之后全屏 AOE，",-1)),l(n,{name:"tank"}),l(n,{name:"dps"}),s[3]||(s[3]=S("T 和 DPS 也别忘了放自己的场地 / 团队减伤技能。",-1))]),t("p",null,[s[4]||(s[4]=S("最后 BOSS 召唤 4 个黑球与玩家连线，黑球会向连线方向放扇形 AOE，注意尽可能向外引导，也可以所有人向左 / 向右移动，将其横着引导。AOE 一共会放 2 次，中间会穿插依次 BOSS 的扇形 AOE 技能，",-1)),l(n,{name:"healer"}),s[5]||(s[5]=S("治疗注意抬血。",-1))])])}const f=O(r,[["render",a]]);export{k as __pageData,f as default};
